// src/components/Dashboard/ReleaseView/ReleaseQEHome.js
import React, { useMemo } from 'react';

/**
 * [PH1-F4] Embed Excel "Daily Dashboard" sheet.
 * - For EDIT & SAVE -> set REACT_APP_SP_DSR_URL to the direct SharePoint file URL
 *   (e.g., https://cibc.sharepoint.com/:x:/r/sites/.../TQI%20CBPT%20Releases%20DSR%20as%20Oct%2008.xlsm)
 *   We append ?web=1&action=edit so users can edit in-place with their SP auth.
 * - Fallback -> local /files/TQI CBPT Releases DSR as of Oct 08.xlsm (view-only).
 */
export default function ReleaseQEHome({ release }) {
  const sheetHint = 'ActiveCell=Daily%20Dashboard!A1';

  const embedSrc = useMemo(() => {
    const sp = process.env.REACT_APP_SP_DSR_URL; // provide direct SP file URL for true editing
    if (sp) {
      // SharePoint edit embed (saves changes server-side when user has perms)
      const sep = sp.includes('?') ? '&' : '?';
      return `${sp}${sep}web=1&action=edit&wdAllowInteractivity=True&${sheetHint}`;
    }

    // Local preview (read-only). Ensure the file is under /public/files
    const localName = 'TQI CBPT Releases DSR as of Oct 08.xlsm';
    const localUrl = `${window.location.origin}/files/${encodeURIComponent(localName)}`;
    return `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(localUrl)}&${sheetHint}`;
  }, []);

  return (
    <div>
      <div className="muted" style={{ marginBottom: 8 }}>
        Release QE Home for <b>{release || '—'}</b>
      </div>

      {/* [PH1-F4] Embedded Excel */}
      <div style={{ height: '78vh', borderRadius: 12, overflow: 'hidden', background: '#0f162a' }}>
        <iframe
          title="TQI CBPT Releases DSR — Daily Dashboard"
          src={embedSrc}
          style={{ width: '100%', height: '100%', border: 0 }}
          allowFullScreen
        />
      </div>
    </div>
  );
}
